function kthSmallest(root: TreeNode | null, k: number): number {
  // Итеративный симметричный обход (in-order): левое поддерево, узел, правое.
  // В BST он выдаёт значения строго по возрастанию
  const stack: TreeNode[] = [];
  let node = root;

  while (node !== null || stack.length > 0) {
    // Спускаемся влево до упора, запоминая путь
    while (node !== null) {
      stack.push(node);
      node = node.left;
    }

    // Вершина стека — наименьший ещё не посещённый узел
    node = stack.pop()!;
    k--;
    if (k === 0) {
      // Это k-й по счёту узел обхода — останавливаемся сразу
      return node.val;
    }

    // Следующие по величине значения — в правом поддереве
    node = node.right;
  }

  // По условию k <= n, сюда не дойдём
  return -1;
}

// Время: O(h + k) — спуск к минимуму и k шагов обхода
// Память: O(h) — стек, h — высота дерева
